function activeProfile() { return family.profiles.find(profile => profile.id === family.activeId) || family.profiles[0]; }
function activateProfile(profileId) { const profile = family.profiles.find(item => item.id === profileId); if (!profile) return; family.activeId = profile.id; saveFamily(); state.parentOpen = false; state.childAccessUnlocked = false; state.route = "play"; setToast(state.lang === "el" ? `Έτοιμο το προφίλ του/της ${profile.name}.` : `${profile.name}'s profile is ready.`); }
function setToast(message) { state.toast = message; render(); window.clearTimeout(window.__paizoToast); window.__paizoToast = window.setTimeout(() => { state.toast = ""; render(); }, 3000); }
function shuffle(list) { return list.slice().sort(() => Math.random() - .5); }
function randomId() { return (crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(16).slice(2)}`); }
function playTone(ok) { if (!state.sound || !window.AudioContext) return; try { const context = new AudioContext(); const oscillator = context.createOscillator(); const gain = context.createGain(); oscillator.type = "sine"; oscillator.frequency.value = ok ? 680 : 300; gain.gain.setValueAtTime(.05, context.currentTime); gain.gain.exponentialRampToValueAtTime(.001, context.currentTime + .35); oscillator.connect(gain).connect(context.destination); oscillator.start(); oscillator.stop(context.currentTime + .35); } catch {} }
function speak(text) { if (!("speechSynthesis" in window)) return; speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(text); utterance.lang = state.lang === "el" ? "el-GR" : "en-GB"; utterance.rate = .9; speechSynthesis.speak(utterance); }
async function digest(value) { const raw = new TextEncoder().encode(value); const hash = await crypto.subtle.digest("SHA-256", raw); return [...new Uint8Array(hash)].map(byte => byte.toString(16).padStart(2, "0")).join(""); }
async function deriveKey(password, salt) { const material = await crypto.subtle.importKey("raw", new TextEncoder().encode(password), "PBKDF2", false, ["deriveKey"]); return crypto.subtle.deriveKey({ name: "PBKDF2", salt, iterations: 150000, hash: "SHA-256" }, material, { name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]); }
function bytesToBase64(bytes) { return btoa(String.fromCharCode(...new Uint8Array(bytes))); }
function base64ToBytes(value) { return Uint8Array.from(atob(value), character => character.charCodeAt(0)); }
async function encryptedBackup(password) { const salt = crypto.getRandomValues(new Uint8Array(16)); const iv = crypto.getRandomValues(new Uint8Array(12)); const key = await deriveKey(password, salt); const data = new TextEncoder().encode(JSON.stringify({ format: "paizomath-portable-v3", exportedAt: new Date().toISOString(), family })); const encrypted = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, data); return JSON.stringify({ format: "paizomath-encrypted-backup", version: 1, salt: bytesToBase64(salt), iv: bytesToBase64(iv), data: bytesToBase64(encrypted) }, null, 2); }
async function restoreEncryptedBackup(text, password) { const backup = JSON.parse(text); if (backup.format !== "paizomath-encrypted-backup") throw new Error("Invalid backup"); const key = await deriveKey(password, base64ToBytes(backup.salt)); const decrypted = await crypto.subtle.decrypt({ name: "AES-GCM", iv: base64ToBytes(backup.iv) }, key, base64ToBytes(backup.data)); const payload = JSON.parse(new TextDecoder().decode(decrypted)); if (!payload.family?.profiles) throw new Error("Invalid data"); return payload.family; }

function header() { return `<header class="bar"><button class="brand" data-route="home" aria-label="${t("home")}"><img src="images/paizo-logo.png" alt=""><span>${t("brand")}</span></button><div class="bar-actions"><div class="language" aria-label="Language"><button data-language="el" class="${state.lang === "el" ? "active" : ""}">🇬🇷 ΕΛ</button><button data-language="en" class="${state.lang === "en" ? "active" : ""}">🇬🇧 EN</button></div><button class="parent-link" data-support aria-label="${t("parents")}" title="${t("parents")}">${ICONS.parent} <span>${t("parents")}</span></button><button class="button coral" data-route="child-access">${ICONS.play} <span>${t("play")}</span></button></div></header>`; }
function mobileNav() { return `<nav class="mobile-nav" aria-label="${t("home")}"><button data-route="home">${ICONS.home || "⌂"}<span>${t("home")}</span></button><button data-route="child-access">${ICONS.play}<span>${t("play")}</span></button><button data-support aria-label="${t("parents")}" title="${t("parents")}">${ICONS.parent}<span>${t("parents")}</span></button></nav>`; }
function supportModal() { const heading = state.lang === "el" ? "Για Γονείς" : "For parents"; const copy = state.lang === "el" ? `<p>Αγαπητοί συνάδελφοι και εκπαιδευτικοί, 😊</p><p>Θα ήθελα να μοιραστώ μαζί σας μια ψηφιακή εκπαιδευτική εφαρμογή που δημιούργησα, σχεδιασμένη αποκλειστικά για παιδιά προσχολικής και πρώτης σχολικής ηλικίας, η οποία μπορεί να χρησιμοποιηθεί ως υποστηρικτικό εργαλείο στην τάξη ή στο σπίτι.</p><p>Η εφαρμογή προσφέρεται εντελώς δωρεάν, είναι ανοιχτού κώδικα (open-source) και δεν περιέχει απολύτως καμία διαφήμιση ή paywall.</p><h3>🎯 Παιδαγωγικά &amp; Τεχνικά Χαρακτηριστικά:</h3><p>🔊 Ακουστική &amp; Οπτική Επιβράβευση: Θετική ενίσχυση με ήχους που τονώνουν την αυτοπεποίθηση του μαθητή.</p><p>🛡️ Μη Τιμωρητική Διαχείριση Λάθους: Το παιδί δεν απογοητεύεται, αλλά ενθαρρύνεται να δοκιμάσει ξανά, μετατρέποντας το λάθος σε πηγή μάθησης.</p><p>🔄 Προσαρμοστική Επανάληψη (Adaptive Learning): Έξυπνος αλγόριθμος που εντοπίζει τα λάθη του παιδιού και τα επαναφέρει σε εύθετο χρόνο για την οριστική εμπέδωση της γνώσης.</p><p>📶 Πλήρης Offline Λειτουργία: Μπορεί να τρέξει σε οποιοδήποτε tablet ή υπολογιστή χωρίς την ανάγκη σύνδεσης στο διαδίκτυο (ιδανικό για σχολικές αίθουσες).</p><p>📊 Εργαλεία Γονέα/Εκπαιδευτικού: Για τον έλεγχο και την παρακολούθηση της προόδου.</p><p>Μπορείτε να δείτε την αναλυτική παρουσίαση 60 δευτερολέπτων και να δοκιμάσετε την εφαρμογή άμεσα online (χωρίς καμία εγκατάσταση) εδώ:<br>➡️ https://pedia2026.blogspot.com</p><p>Το project αυτό έγινε με πολύ μεράκι για την υποστήριξη της ελεύθερης εκπαίδευσης. Αν το βρείτε χρήσιμο για τους μαθητές σας, θα χαρώ πολύ να ακούσω τις παιδαγωγικές σας παρατηρήσεις! (Στο κάτω μέρος της σελίδας υπάρχει και ένα προαιρετικό QR code για όποιον επιθυμεί να κεράσει έναν καφέ για τα έξοδα συντήρησης). 🙏</p>` : `<p>Hello educators and colleagues! 😊</p><p>As an independent developer, I wanted to share a digital educational web app I’ve built, specifically designed for preschool and early elementary school children. It is perfect as a supplementary tool for the classroom or remote learning.</p><p>This web app is completely free, open-source, and 100% ad-free with absolutely no paywalls.</p><h3>🎯 Pedagogical &amp; Technical Features:</h3><p>🔊 Audio &amp; Visual Reinforcement: Positive feedback with engaging sounds to boost students' confidence and keep them motivated.</p><p>🛡️ Stress-Free Mistake Handling: Non-punitive design that encourages children to try again, transforming errors into valuable learning moments.</p><p>🔄 Adaptive Repetition System: A smart algorithm that tracks missed answers and brings them back at the right time to reinforce and solidify knowledge.</p><p>📶 Full Offline Mode: It can run seamlessly on any tablet or computer without requiring an active internet connection (ideal for classrooms with limited connectivity).</p><p>📊 Teacher/Parent Tools: Features to monitor and track the child's progress easily.</p><p>You can watch a quick 60-second video presentation and test the app instantly in your browser (no installation or download required) here:<br>➡️ https://pedia2026.blogspot.com</p><p>This project was built out of passion to support open education. If you find it useful for your students, I would love to hear your professional feedback and pedagogical insights! (For anyone wishing to support development and hosting costs, a completely voluntary "buy me a coffee" QR code is available at the bottom of the page). 🙏</p>`; return `<div class="support-modal" role="dialog" aria-modal="true" aria-labelledby="support-modal-title"><button class="support-backdrop" id="close-support" aria-label="${ICONS.close}"></button><section class="support-dialog"><button class="support-close" id="close-support-dialog" aria-label="${ICONS.close}">${ICONS.close}</button><div class="modal-kicker">${t("optional")}</div><h2 id="support-modal-title">${heading}</h2><img src="images/paypal-tip-qr-xristos-tsiagkarlis.jpg" alt="PayPal QR"><div class="support-copy">${copy}</div></section></div>`; }
function shortcutGuide() { const title = state.lang === "el" ? "Απλή συντόμευση για το παιδί" : "A simple shortcut for your child"; const text = state.lang === "el" ? "Δεν γίνεται καμία εγκατάσταση εφαρμογής και δεν κατεβαίνει κανένα αρχείο. Ο γονέας ανοίγει τη σελίδα μία φορά και επιλέγει «Προσθήκη στην αρχική οθόνη» από το μενού του browser. Δημιουργείται απλή συντόμευση· το παιδί πατά τη συντόμευση και ανοίγει το παιχνίδι απευθείας, χωρίς να μπαίνει κάθε φορά στο Blogger." : "No app is installed and no file is downloaded. A parent opens the page once and chooses “Add to Home Screen” in the browser menu. This creates a simple shortcut; the child taps it to open the game directly without returning to Blogger each time."; const steps = state.lang === "el" ? ["Android: μενού ⋮ → Προσθήκη στην αρχική οθόνη", "iPhone / iPad: Κοινοποίηση → Προσθήκη στην αρχική οθόνη", "Laptop: προσθήκη στους σελιδοδείκτες του browser"] : ["Android: browser menu ⋮ → Add to Home Screen", "iPhone / iPad: Share → Add to Home Screen", "Laptop: add the page to browser bookmarks"]; return `<section class="shortcut-guide"><div class="shortcut-symbol">${ICONS.home || "⌂"}</div><div><div class="eyebrow">${state.lang === "el" ? "Γονική επιλογή" : "Parent choice"}</div><h2>${title}</h2><p>${text}</p><div class="shortcut-steps">${steps.map((step, index) => `<span><b>${index + 1}</b>${step}</span>`).join("")}</div></div></section>`; }
function emergency112Warning(isGreek = state.lang === "el") { return `<p class="emergency-warning"><strong>${isGreek ? "Προσοχή: Ο αριθμός 112 χρησιμοποιείται ΜΟΝΟ σε πραγματική έκτακτη ανάγκη. Δεν καλούμε ποτέ τον αριθμό αυτό για δοκιμή ή για παιχνίδι." : "Warning: 112 is used ONLY in a real emergency. Never call this number for a test or a game."}</strong></p>`; }
function eu112Credit(isGreek = state.lang === "el") { return `<small class="ec-112-credit">${isGreek ? "Με πληροφορίες από την επίσημη πύλη της Ευρωπαϊκής Επιτροπής (© Ευρωπαϊκή Ένωση, CC BY 4.0)." : "With information from the official European Commission portal (© European Union, CC BY 4.0)."}</small>`; }
function privacyNotice(isGreek = state.lang === "el") { return isGreek ? "Η εφαρμογή παρέχεται “ως έχει” (as is) για εκπαιδευτικούς σκοπούς. Το PaizoMath δεν συλλέγει, δεν μεταδίδει και δεν διαμοιράζεται προσωπικά δεδομένα σε εξωτερικό server. Τα στοιχεία προφίλ, το γονικό PIN και η πρόοδος που καταχωρεί ο γονέας αποθηκεύονται μόνο τοπικά στη συσκευή του μέσω του browser και μπορούν να διαγραφούν από τον ίδιο." : "The app is provided “as is” for educational purposes. PaizoMath does not collect, transmit or share personal data with an external server. Profile details, the parent PIN and progress entered by a parent are stored only locally on that parent’s device through the browser and can be deleted by the parent."; }
const PUBLIC_SHARE_URL = "https://christsiagkarlis-byte.github.io/paizomath/";
function socialShareSection(context = "public") { const el = state.lang === "el"; const title = context === "parent" ? (el ? "Κοινοποιήστε την εκπαιδευτική εμπειρία" : "Share this learning experience") : (el ? "Μοιραστείτε το PaizoMath" : "Share PaizoMath"); const note = el ? "Τα κουμπιά ανοίγουν νέο παράθυρο κοινοποίησης. Δεν συνδέονται με προσωπικό λογαριασμό του παιδιού." : "These controls open a new sharing window. They do not connect to a child’s personal account."; const text = el ? "Δείτε το PaizoMath: δωρεάν, δίγλωσση μαθησιακή εμπειρία για παιδιά." : "Explore PaizoMath: a free bilingual learning experience for children."; const url = encodeURIComponent(PUBLIC_SHARE_URL); const share = encodeURIComponent(`${text} ${PUBLIC_SHARE_URL}`); const subject = encodeURIComponent(el ? "PaizoMath — δωρεάν εκπαιδευτική εμπειρία" : "PaizoMath — free learning experience"); const links = [["Facebook", `https://www.facebook.com/sharer/sharer.php?u=${url}`, "fb"], ["X", `https://twitter.com/intent/tweet?text=${share}`, "x"], ["WhatsApp", `https://wa.me/?text=${share}`, "wa"], ["Telegram", `https://t.me/share/url?url=${url}&text=${encodeURIComponent(text)}`, "tg"], ["LinkedIn", `https://www.linkedin.com/sharing/share-offsite/?url=${url}`, "in"], ["Email", `mailto:?subject=${subject}&body=${share}`, "mail"]]; return `<section class="social-share social-share-${context}" aria-label="${title}"><div><div class="eyebrow">${el ? "Κοινοποίηση" : "Sharing"}</div><h2>${title}</h2><p>${note}</p></div><nav class="social-share-links" aria-label="${title}">${links.map(([label, href, key]) => `<a class="share-link share-${key}" href="${href}" target="_blank" rel="noopener noreferrer" aria-label="${el ? "Κοινοποίηση μέσω" : "Share via"} ${label}"><b>${key === "fb" ? "f" : key === "x" ? "X" : key === "wa" ? "WA" : key === "tg" ? "TG" : key === "in" ? "in" : "✉"}</b><span>${label}</span></a>`).join("")}</nav></section>`; }
function firstAidSourcesPanel() { const isGreek = state.lang === "el"; const title = isGreek ? "Πρώτες Βοήθειες: δωρεάν, ασφαλές εκπαιδευτικό μάθημα" : "First aid: a free, safety-first learning topic"; const text = isGreek ? "Οι ερωτήσεις δημιουργήθηκαν ειδικά για το PaizoMath, με απλή γλώσσα για την ηλικία του παιδιού και ενημέρωση από δημόσια προσβάσιμες πηγές. Δεν είναι πιστοποίηση πρώτων βοηθειών και δεν αντικαθιστούν ενήλικα, το 112 ή πρακτική εκπαίδευση." : "The questions were created specifically for PaizoMath, using simple language for the child's age and publicly accessible sources. They are not first-aid certification and do not replace an adult, 112 or practical training."; const sources = isGreek ? [["Ευρωπαϊκή Επιτροπή — 112", "https://digital-strategy.ec.europa.eu/en/policies/112"], ["European Resuscitation Council — Guidelines 2025 / Download Centre", "https://www.erc.edu/download-centre/"], ["St John Ambulance — First aid advice", "https://www.sja.org.uk/first-aid-advice/"], ["IFRC — First aid guidelines", "https://www.ifrc.org/document/international-first-aid-resuscitation-and-education-guidelines"]] : [["European Commission — 112", "https://digital-strategy.ec.europa.eu/en/policies/112"], ["European Resuscitation Council — Guidelines 2025 / Download Centre", "https://www.erc.edu/download-centre/"], ["St John Ambulance — First aid advice", "https://www.sja.org.uk/first-aid-advice/"], ["IFRC — First aid guidelines", "https://www.ifrc.org/document/international-first-aid-resuscitation-and-education-guidelines"]]; return `<section class="first-aid-sources"><div class="first-aid-source-mark">✚</div><div><div class="eyebrow">${isGreek ? "Ενημέρωση γονέα" : "Parent information"}</div><h2>${title}</h2><p>${text}</p><p class="emergency-callout"><b>${isGreek ? "Πραγματικό επείγον:" : "Real emergency:"}</b> ${isGreek ? "το παιδί ζητά αμέσως ενήλικα και καλείται το 112." : "the child gets an adult immediately and 112 is called."}</p>${emergency112Warning(isGreek)}${eu112Credit(isGreek)}<div class="first-aid-source-links">${sources.map(source => `<a href="${source[1]}" target="_blank" rel="noopener noreferrer">${source[0]} ↗</a>`).join("")}</div><button class="text-button terms-link" data-route="terms">${isGreek ? "Όροι χρήσης & ασφάλεια" : "Terms of use & safety"} ${ICONS.next}</button></div></section>`; }
function terms() { const isGreek = state.lang === "el"; const copy = isGreek ? { eyebrow: "Γονική ενημέρωση", title: "Όροι Χρήσης & Ασφάλεια Εφαρμογής PaizoMath", back: "Επιστροφή στη διαχείριση γονέα", sections: [["1. Γενικές Πληροφορίες", "Το PaizoMath είναι μια δωρεάν, εκπαιδευτική εφαρμογή ανοιχτού κώδικα (open-source) που μπορεί να φιλοξενείται στο GitHub ή σε άλλο στατικό hosting. Ο πρωταρχικός σκοπός της ενότητας «Πρώτες Βοήθειες» είναι η ευαισθητοποίηση και η εισαγωγική επίγνωση των παιδιών σε θέματα ασφάλειας."], ["2. Ιατρική Αποποίηση Ευθύνης", "Οι πληροφορίες και οι ερωτήσεις που περιλαμβάνονται στην εφαρμογή παρέχονται αποκλειστικά για γενικούς εκπαιδευτικούς σκοπούς. Δεν αποτελούν ιατρικές συμβουλές, κλινικές οδηγίες ή επαγγελματική εκπαίδευση πρώτων βοηθειών. Το PaizoMath δεν αντικαθιστά σε καμία περίπτωση τα πιστοποιημένα μαθήματα πρώτων βοηθειών, τη γνώμη επαγγελματία υγείας ή τις οδηγίες των επίσημων υπηρεσιών έκτακτης ανάγκης."], ["3. Πραγματικό επείγον", "Σε περίπτωση πραγματικού κινδύνου, η πρώτη ενέργεια πρέπει να είναι η άμεση ενημέρωση ενός ενήλικα και η κλήση στον Ευρωπαϊκό Αριθμό Έκτακτης Ανάγκης 112."], ["4. Πηγές & Πνευματική Ιδιοκτησία", "Η εφαρμογή χρησιμοποιεί πρωτότυπες ερωτήσεις και δεν αναπαράγει, αντιγράφει ή ενσωματώνει προστατευόμενα κείμενα, λογότυπα, εικόνες ή διαγράμματα τρίτων φορέων. Οι σύνδεσμοι προς επίσημους οργανισμούς, όπως η Ευρωπαϊκή Επιτροπή, το ERC, το St John Ambulance και το IFRC, λειτουργούν αποκλειστικά ως ενημερωτικές παραπομπές προς πρωτογενείς δημόσιες πηγές και δεν υποδηλώνουν συνεργασία, έγκριση ή χορηγία από τους εν λόγω φορείς."], ["5. Οικονομική Υποστήριξη", "Η πρόσβαση στο PaizoMath είναι 100% δωρεάν για όλους. Η επιλογή «Buy Me a Coffee» αποτελεί προαιρετικό φιλοδώρημα (tipping) και εθελοντική χειρονομία υποστήριξης προς τον δημιουργό για την κάλυψη των εξόδων ανάπτυξης. Δεν αποτελεί έρανο, φιλανθρωπική δωρεά ή εμπορική συναλλαγή αγοράς προϊόντος."]] } : { eyebrow: "Parent information", title: "PaizoMath Terms of Use & App Safety", back: "Return to parent management", sections: [["1. General information", "PaizoMath is a free, open-source educational app that may be hosted on GitHub or another static host. The primary purpose of the First Aid topic is children’s awareness and introductory understanding of safety."], ["2. Medical disclaimer", "The information and questions in the app are provided only for general educational purposes. They are not medical advice, clinical guidance or professional first-aid training. PaizoMath does not replace certified first-aid courses, the opinion of a health professional or instructions from official emergency services."], ["3. A real emergency", "In case of real danger, the first action must be to tell an adult immediately and call the European emergency number 112."], ["4. Sources & intellectual property", "The app uses original questions and does not reproduce, copy or embed protected text, logos, images or diagrams from third parties. Links to official organisations, including the European Commission, ERC, St John Ambulance and IFRC, are informational references to primary public sources only and do not imply collaboration, approval or sponsorship by those organisations."], ["5. Financial support", "Access to PaizoMath is 100% free for everyone. The Buy Me a Coffee option is an optional tip and voluntary gesture of support for the creator’s development costs. It is not a fundraiser, charitable donation or commercial transaction for the purchase of a product."]] }; return pageFrame(`<main class="terms-page"><section class="terms-card"><div class="eyebrow">${copy.eyebrow}</div><h1>${copy.title}</h1>${copy.sections.map((section, index) => `<article class="terms-section ${index === 2 ? "emergency-terms" : ""}"><h2>${section[0]}</h2><p>${section[1]}</p></article>`).join("")}<button class="button quiet terms-back" data-route="parents">${ICONS.back} ${copy.back}</button></section></main>`); }
function terms() { const el = state.lang === "el"; const sections = el ? [["1. Φύση της Εφαρμογής", "Η παρούσα ψηφιακή εκπαιδευτική εφαρμογή αποτελεί λογισμικό ανοιχτού κώδικα (open-source) και παρέχεται εντελώς δωρεάν για υποστηρικτική χρήση στην τάξη ή στο σπίτι. Δεν περιλαμβάνει διαφημίσεις, αγορές εντός της εφαρμογής (paywalls) ή κρυφές χρεώσεις."], ["2. Ασφάλεια & Τοπική Αποθήκευση Δεδομένων", privacyNotice(true) + " Μπορούν να διαγραφούν ανά πάσα στιγμή, για παράδειγμα με εκκαθάριση των δεδομένων περιήγησης της συσκευής."], ["3. Ιατρική Αποποίηση Ευθύνης", "Οι πληροφορίες και οι ερωτήσεις, συμπεριλαμβανομένης της ενότητας Πρώτων Βοηθειών, παρέχονται αποκλειστικά για γενικούς εκπαιδευτικούς σκοπούς. Δεν αποτελούν ιατρικές συμβουλές, κλινικές οδηγίες ή επαγγελματική εκπαίδευση πρώτων βοηθειών και δεν αντικαθιστούν πιστοποιημένα μαθήματα, επαγγελματία υγείας ή επίσημες υπηρεσίες έκτακτης ανάγκης."], ["4. Πραγματικό επείγον", "Σε περίπτωση πραγματικού κινδύνου, η πρώτη ενέργεια πρέπει να είναι η άμεση ενημέρωση ενός έμπιστου ενήλικα και η κλήση στον Ευρωπαϊκό Αριθμό Έκτακτης Ανάγκης 112."], ["5. Πηγές & Πνευματική Ιδιοκτησία", "Η εφαρμογή χρησιμοποιεί πρωτότυπες ερωτήσεις. Δεν αναπαράγονται ή ενσωματώνονται προστατευμένα κείμενα, λογότυπα, εικόνες, διαγράμματα ή αρχεία τρίτων. Οι εξωτερικοί σύνδεσμοι προς την Ευρωπαϊκή Επιτροπή, το ERC, το St John Ambulance και το IFRC είναι μόνο ενημερωτικές παραπομπές και δεν υποδηλώνουν συνεργασία, έγκριση ή χορηγία."], ["6. Προαιρετική Υποστήριξη", "Η οικονομική ενίσχυση μέσω του συνδέσμου ή QR code («κέρασμα καφέ») είναι 100% προαιρετική, αποτελεί εθελοντικό φιλοδώρημα προς τον δημιουργό για τα έξοδα συντήρησης και δεν ξεκλειδώνει επιπλέον λειτουργίες. Δεν αποτελεί έρανο ή αγορά προϊόντος/υπηρεσίας."], ["7. Άδεια κώδικα", "Ο πρωτότυπος κώδικας του PaizoMath διατίθεται με άδεια MIT. Η άδεια αυτή δεν δίνει δικαιώματα αναπαραγωγής υλικού τρίτων που παρέχεται μόνο μέσω εξωτερικής παραπομπής."]] : [["1. Nature of the app", "This educational digital application is open-source software and is provided entirely free for supportive use in the classroom or at home. It contains no advertising, in-app purchases, paywalls or hidden charges."], ["2. Security & local data storage", privacyNotice(false) + " They can be deleted at any time, for example by clearing browsing data on the device."], ["3. Medical disclaimer", "The information and questions, including the First Aid topic, are provided only for general educational purposes. They are not medical advice, clinical guidance or professional first-aid training and do not replace certified courses, a health professional or official emergency services."], ["4. A real emergency", "In the case of real danger, the first action must be to tell a trusted adult immediately and call the European emergency number 112."], ["5. Sources & intellectual property", "The app uses original questions. It does not reproduce or embed protected third-party text, logos, images, diagrams or files. External links to the European Commission, ERC, St John Ambulance and IFRC are informational references only and do not imply collaboration, approval or sponsorship."], ["6. Optional support", "Financial support through the link or QR code is 100% optional, is a voluntary tip to the creator for maintenance costs and does not unlock additional features. It is not a fundraiser or a purchase of a product or service."], ["7. Code licence", "The original PaizoMath code is made available under the MIT licence. This licence does not grant rights to reproduce third-party material available only through an external reference."]]; return pageFrame(`<main class="terms-page"><section class="terms-card"><div class="eyebrow">${el ? "Γονική ενημέρωση" : "Parent information"}</div><h1>${el ? "Όροι Χρήσης & Ασφάλεια Δεδομένων" : "Terms of Use & Data Safety"}</h1>${sections.map((section, index) => `<article class="terms-section ${index === 3 ? "emergency-terms" : ""}"><h2>${section[0]}</h2><p>${section[1]}</p>${index === 3 ? emergency112Warning(el) + eu112Credit(el) : ""}</article>`).join("")}<button class="button quiet terms-back" data-route="parents">${ICONS.back} ${el ? "Επιστροφή στη διαχείριση γονέα" : "Return to parent management"}</button></section></main>`); }
function publicFooter() { return `<footer class="public-footer"><a href="terms.html">${state.lang === "el" ? "Όροι Χρήσης & Ασφάλεια" : "Terms of Use & Safety"}</a><span class="privacy-footer-note">${privacyNotice()}</span></footer>`; }
function pageFrame(content, extra = "") { const share = state.route === "home" ? socialShareSection("public") : state.route === "parents" && state.parentOpen ? socialShareSection("parent") : ""; return `<div class="paizo ${extra}">${header()}${content}${share}${publicFooter()}${mobileNav()}${state.supportOpen ? supportModal() : ""}${state.toast ? `<div class="toast" role="status">${esc(state.toast)}</div>` : ""}</div>`; }

function home() { const supportHeading = state.lang === "el" ? "Προαιρετική υποστήριξη και ιδιωτικότητα" : "Optional support and privacy"; const qrHint = state.lang === "el" ? "Σκανάρετε μόνο αν το επιλέξετε." : "Scan only if you choose to."; return pageFrame(`<main><section class="hero"><div class="hero-copy"><div class="eyebrow">✦ ${t("journey")}</div><h1>${t("hero").replace("παιχνίδι.", "<em>παιχνίδι.</em>").replace("a game.", "<em>a game.</em>")}</h1><p>${t("heroText")}</p><div class="hero-actions"><button class="button coral large" data-route="child-access">${t("open")} ${ICONS.next}</button><button class="button quiet large" data-route="intro">${t("intro")} ${ICONS.next}</button></div><div class="hero-notes"><span>◉ ${t("local")}</span><span>${ICONS.star} ${state.lang === "el" ? "Μικρές νίκες κάθε μέρα" : "Small wins every day"}</span></div></div><div class="hero-art"><img src="images/learning-workbench-hero.jpg" alt=""></div></section><section class="section lesson-section"><div class="eyebrow">${t("lessons")}</div><div class="section-title"><h2>${state.lang === "el" ? "Ένας κόσμος από μαθήματα." : "A world of lessons."}</h2><button class="text-button" data-route="child-access">${t("choose")} ${ICONS.next}</button></div><div class="subject-grid">${TOPICS.map(topic => `<button class="subject-card" data-topic="${topic[0]}"><span class="subject-icon">${topic[1]}</span><span><strong>${state.lang === "el" ? topic[2] : topic[3]}</strong><small>${esc(topicDescription(topic[0]))}</small><i>${t("ten")}</i></span></button>`).join("")}</div></section><section class="support-section support-section-complete" aria-label="${supportHeading}"><div class="home-support-copy"><div class="eyebrow">${t("optional")}</div><h2>${supportHeading}</h2><section class="support-message-section">${exactPayPalText()}</section>${privacySupportSection()}</div><div class="home-support-qr"><img src="images/paypal-tip-qr-xristos-tsiagkarlis.jpg" alt="PayPal QR code"><small>${qrHint}</small><button class="text-button home-support-open" data-support>${state.lang === "el" ? "Μεγάλωσε τον QR και το μήνυμα" : "Open QR and message"} ${ICONS.next}</button></div></section></main>`); }

const INTRO_STAGES = [
  ["images/paizo-kai-mathaino-book-banner.gif", "Παίζω και Μαθαίνω.", "Play and Learn.", "Μια δωρεάν, δίγλωσση μαθησιακή εμπειρία για μικρά καθημερινά βήματα γνώσης.", "A free bilingual learning experience for small everyday steps of discovery."],
  ["images/subjects-collage.jpg", "21 θεματικές για εξερεύνηση.", "21 themes to explore.", "Από τα μαθηματικά και τη γλώσσα έως την τεχνολογία και την ασφάλεια, όλα τα μαθήματα βρίσκονται στην ίδια εφαρμογή.", "From maths and language to technology and safety, every topic lives in the same application.", "topics"],
  ["images/learning-workbench-hero.jpg", "Μάθηση σε δύο γλώσσες.", "Learning in two languages.", "Ο γονέας επιλέγει Ελληνικά ή English και η διεπαφή, οι ερωτήσεις και η ανάγνωση ακολουθούν την ίδια γλώσσα.", "A parent chooses Greek or English, and the interface, questions and read-aloud controls follow the same language."],
  ["images/subjects-collage.jpg", "Κάθε γύρος είναι νέα ανακάλυψη.", "Every round is a new discovery.", "Κάθε μάθημα δίνει δέκα διαφορετικές ερωτήσεις. Οι κύκλοι αποθηκεύονται ανά παιδί, θέμα και γλώσσα ώστε να μην επαναλαμβάνονται πριν ολοκληρωθεί ο κύκλος.", "Each lesson gives ten different questions. Cycles are saved by child, topic and language, so prompts do not repeat until the cycle is completed."],
  ["images/learning-workbench-hero.jpg", "Το λάθος γίνεται επόμενη ευκαιρία.", "A mistake becomes the next opportunity.", "Με ήχους ενθάρρυνσης, οπτική επιβράβευση και ήρεμη επανάληψη λαθών, το παιδί προχωρά χωρίς τιμωρία ή βιασύνη.", "With encouraging sounds, visual celebration and a calm mistake review, children move forward without punishment or rush."],
  ["images/parent-child-learning.jpg", "Πρώτες Βοήθειες: ασφάλεια πρώτα.", "First aid: safety first.", "Η ενότητα είναι δωρεάν και προσαρμόζεται στις ηλικίες 6–8, 9–11 και 12–15. Μαθαίνουμε επίγνωση, ασφάλεια και αναζήτηση βοήθειας — όχι ιατρικές πράξεις.", "This free topic adapts to ages 6–8, 9–11 and 12–15. It teaches awareness, safety and asking for help — not medical procedures."],
  ["images/paizo-logo.png", "Σε πραγματικό επείγον: ενήλικας + 112.", "In a real emergency: adult + 112.", "Το παιδί μένει σε ασφαλές σημείο, ενημερώνει αμέσως έναν έμπιστο ενήλικα και καλείται το 112. Η ενότητα δεν αντικαθιστά πιστοποιημένη εκπαίδευση ή επαγγελματική βοήθεια.", "The child stays in a safe place, tells a trusted adult immediately and 112 is called. The topic does not replace certified training or professional help."],
  ["images/paizo-logo.png", "Πηγές Πρώτων Βοηθειών με σεβασμό.", "First-aid sources, used with respect.", "Οι ερωτήσεις είναι πρωτότυπες και ενημερώνονται από δημόσια προσβάσιμες πηγές. Δεν αντιγράφουμε κείμενα, λογότυπα, εικόνες ή οδηγίες φορέων.", "Questions are original and informed by publicly accessible sources. We do not copy organisations’ text, logos, images or instructions.", "sources"],
  ["images/parent-child-learning.jpg", "Ο γονέας έχει τον έλεγχο.", "Parents stay in control.", "Με γονικό PIN, έως 12 παιδικά προφίλ, τοπική πρόοδο και κρυπτογραφημένο backup/restore, τα δεδομένα παραμένουν στη συσκευή.", "With a parent PIN, up to 12 child profiles, local progress and encrypted backup/restore, data stays on the device."],
  ["images/paypal-tip-qr-xristos-tsiagkarlis.jpg", "Έτοιμοι να παίξουμε;", "Ready to play?", "Το PaizoMath παραμένει δωρεάν. Η στήριξη μέσω PayPal είναι προαιρετική· πατήστε «Συνέχεια στο παιχνίδι» για να διαλέξετε παιδικό προφίλ και μάθημα.", "PaizoMath remains free. PayPal support is optional; choose “Continue to play” to select a child profile and a lesson."]
];
INTRO_STAGES.splice(1, 1,
  ["images/subjects-collage.jpg", "21 θεματικές: γνώσεις βάσης.", "21 topics: core discovery.", "Μαθηματικά, γνώσεις, γλώσσα, επιστήμες, ιστορία, γεωγραφία και ψηφιακές δεξιότητες. Δες τι εξερευνά το παιδί σε κάθε μάθημα.", "Mathematics, knowledge, language, science, history, geography and digital skills. See what children explore in every lesson.", "topics-0"],
  ["images/learning-workbench-hero.jpg", "21 θεματικές: δεξιότητες ζωής.", "21 topics: life skills.", "Καλλιτεχνικά, αγγλικά, αξίες, φυσική αγωγή, πολιτική αγωγή, δεξιότητες και οικονομικός γραμματισμός.", "Art, English, values, physical education, civic education, skills and financial literacy.", "topics-1"],
  ["images/parent-child-learning.jpg", "21 θεματικές: ψηφιακό αύριο & ασφάλεια.", "21 topics: digital future & safety.", "Ψηφιακή ασφάλεια, ψηφιακά πορτοφόλια, ασφάλεια στο διαδίκτυο, ΤΝ, πράσινη τεχνολογία, γυμνάσιο και Πρώτες Βοήθειες.", "Digital safety, digital wallets, online safety, AI, green technology, secondary school and First Aid.", "topics-2"]
);
INTRO_STAGES[11] = ["images/paypal-tip-qr-xristos-tsiagkarlis.jpg", "Ένα μικρό ευχαριστώ κρατά το project ζωντανό.", "A small thank-you keeps the project alive.", "Διαβάστε το μήνυμα του δημιουργού και, μόνο αν το θέλετε, σκανάρετε τον QR για προαιρετικό PayPal tip. Η πρόσβαση στο PaizoMath παραμένει δωρεάν.", "Read the creator’s message and, only if you wish, scan the QR for a voluntary PayPal tip. PaizoMath remains free to use.", "support"];
function detailedIntroTopicList(groupIndex) { const groups = [TOPICS.slice(0, 7), TOPICS.slice(7, 14), TOPICS.slice(14, 21)]; const topics = groups[groupIndex] || []; return `<div class="intro-topic-list detailed-topic-list">${topics.map((topic, index) => `<article><span class="intro-topic-number">${String(groupIndex * 7 + index + 1).padStart(2, "0")}</span><div><b>${topic[1]} ${state.lang === "el" ? topic[2] : topic[3]}</b><small>${esc(topicDescription(topic[0]))}</small></div></article>`).join("")}</div>`; }
function exactPayPalText() { return state.lang === "el" ? `<p><strong>Γίνε ο Χορηγός της Καφεΐνης μου! ☕️🦖</strong></p><p>Αυτό το app είναι το προσωπικό μου «παιδί» (side-project) εκτός του ωραρίου της κανονικής μου δουλειάς σε εταιρεία. Είναι δωρεάν, θα παραμείνει δωρεάν για πάντα και δεν θα σας ζητήσει ποτέ κάρτα για να δουλέψει! Αν όμως θέλετε να βάλετε ένα χεράκι στη συντήρησή του, σκανάρετε το QR και στείλτε ένα ελεύθερο φιλοδώρημα μέσω PayPal.</p>` : `<p><strong>Become my Caffeine Sponsor! ☕️🦖</strong></p><p>This app is my personal “baby” (side project), created outside my normal working hours. It is free, will remain free, and will never ask for a card to work. If you would like to help with maintenance, scan the QR code and send a voluntary tip through PayPal.</p>`; }
function privacySupportSection() { const heading = state.lang === "el" ? "Ασφάλεια και τοπική αποθήκευση" : "Privacy and local storage"; return `<section class="privacy-support-section"><h3>${heading}</h3><p>${privacyNotice()}</p></section>`; }
function introSupportPanel() { const heading = state.lang === "el" ? "Το μήνυμα του δημιουργού" : "The creator’s message"; const hint = state.lang === "el" ? "Το μήνυμα και η ενημέρωση ιδιωτικότητας εμφανίζονται παρακάτω ως δύο ξεχωριστές ενότητες." : "The creator’s message and privacy notice are shown below as two separate sections."; return `<section class="intro-support-panel" aria-label="${heading}"><div class="intro-qr-column"><img src="images/paypal-tip-qr-xristos-tsiagkarlis.jpg" alt="PayPal QR"><strong>${state.lang === "el" ? "Προαιρετική υποστήριξη" : "Optional support"}</strong><small>${state.lang === "el" ? "Η πρόσβαση παραμένει δωρεάν." : "Access remains free."}</small></div><div class="intro-support-copy"><h2>${heading}</h2><p class="support-scroll-hint">${hint}</p><div class="support-scroll-copy" tabindex="0" aria-label="${heading}"><section class="support-message-section">${exactPayPalText()}</section>${privacySupportSection()}</div></div></section>`; }
function supportModal() { const heading = state.lang === "el" ? "Για Γονείς · Προαιρετική στήριξη" : "For parents · Optional support"; return `<div class="support-modal" role="dialog" aria-modal="true" aria-labelledby="support-modal-title"><button class="support-backdrop" id="close-support" aria-label="${ICONS.close}"></button><section class="support-dialog exact-support-dialog"><button class="support-close" id="close-support-dialog" aria-label="${ICONS.close}">${ICONS.close}</button><div class="modal-kicker">${t("optional")}</div><h2 id="support-modal-title">${heading}</h2><img src="images/paypal-tip-qr-xristos-tsiagkarlis.jpg" alt="PayPal QR"><div class="support-copy exact-support-copy"><section class="support-message-section">${exactPayPalText()}</section>${privacySupportSection()}</div></section></div>`; }
function intro() { const stage = INTRO_STAGES[state.introStage]; const final = state.introStage === INTRO_STAGES.length - 1; const marker = stage[5] || ""; const topicMatch = /^topics-(\d)$/.exec(marker); const topicGroup = topicMatch ? Number(topicMatch[1]) : -1; const musicStatus = state.musicOn ? `<div class="music-status"><span class="equalizer"><i></i><i></i><i></i></span>${t("musicPlaying")}</div>` : state.musicAttempted ? `<div class="music-status muted">${t("musicBlocked")}</div>` : ""; return `<div class="intro-page ${marker === "support" ? "intro-page-support" : ""}"><div class="intro-toolbar"><button class="brand compact" data-route="home"><img src="images/paizo-logo.png" alt="">${t("brand")}</button><div class="intro-tools"><button class="music-control ${state.musicOn ? "active" : ""}" id="music-toggle" aria-pressed="${state.musicOn}">${ICONS.music} ${t("music")}</button><label class="volume"><span class="sr-only">${t("music")}</span><input id="music-volume" type="range" min="0.05" max="0.45" step="0.01" value="${audio.volume}"></label><button class="intro-exit" data-route="home">${ICONS.close} <span>${t("home")}</span></button></div></div><main class="intro-main"><div class="intro-progress-head"><span>${t("presentation")}</span><strong>${String(state.introStage + 1).padStart(2, "0")} / ${String(INTRO_STAGES.length).padStart(2, "0")}</strong></div><div class="intro-progress"><span style="width:${((state.introStage + 1) / INTRO_STAGES.length) * 100}%"></span></div><section class="intro-stage"><div class="intro-image"><img src="${stage[0]}" alt=""></div><div class="intro-copy"><div class="eyebrow">${t("stage")} ${state.introStage + 1} · 60″</div><h1>${state.lang === "el" ? stage[1] : stage[2]}</h1><p>${state.lang === "el" ? stage[3] : stage[4]}</p>${topicGroup >= 0 ? detailedIntroTopicList(topicGroup) : ""}${marker === "sources" ? introSourceList() : ""}${marker === "support" ? introSupportPanel() : ""}${musicStatus}<div class="intro-actions"><button class="button quiet" id="intro-prev" ${state.introStage === 0 ? "disabled" : ""}>${ICONS.back} ${t("previousStage")}</button>${final ? `<button class="button coral" data-route="child-access">${t("continueGame")} ${ICONS.next}</button>` : `<button class="button coral" id="intro-next">${t("nextStage")} ${ICONS.next}</button>`}</div></div></section><div class="intro-dots" aria-hidden="true">${INTRO_STAGES.map((_, index) => `<i class="${index === state.introStage ? "active" : index < state.introStage ? "done" : ""}"></i>`).join("")}</div></main></div>`; }
function introTopicList() { const groups = state.lang === "el" ? [["Γνώσεις βάσης", TOPICS.slice(0, 7)], ["Δεξιότητες ζωής", TOPICS.slice(7, 14)], ["Ψηφιακό αύριο", TOPICS.slice(14)]] : [["Core discovery", TOPICS.slice(0, 7)], ["Life skills", TOPICS.slice(7, 14)], ["Digital future", TOPICS.slice(14)]]; return `<div class="intro-topic-list">${groups.map(([label, topics]) => `<section><b>${label}</b><div>${topics.map(topic => `<span>${topic[1]} ${state.lang === "el" ? topic[2] : topic[3]}</span>`).join("")}</div></section>`).join("")}</div>`; }
function introSourceList() { const sources = [["European Commission — 112", "https://digital-strategy.ec.europa.eu/en/policies/112"], ["European Resuscitation Council — Guidelines 2025", "https://www.erc.edu/download-centre/"], ["St John Ambulance — First aid advice", "https://www.sja.org.uk/first-aid-advice/"], ["IFRC — First aid guidelines", "https://www.ifrc.org/document/international-first-aid-resuscitation-and-education-guidelines"]]; return `<div class="intro-sources"><b>${state.lang === "el" ? "Δημόσια προσβάσιμες πηγές" : "Publicly accessible sources"}</b>${sources.map(([title, url]) => `<a href="${url}" target="_blank" rel="noopener noreferrer">${title} ↗</a>`).join("")}${emergency112Warning()}${eu112Credit()}<small>${state.lang === "el" ? "Οι σύνδεσμοι δεν δηλώνουν έγκριση ή συνεργασία των φορέων με το PaizoMath." : "Links do not indicate endorsement of or partnership with PaizoMath."}</small></div>`; }
function legacyIntro() { const stage = INTRO_STAGES[state.introStage]; const final = state.introStage === INTRO_STAGES.length - 1; const musicStatus = state.musicOn ? `<div class="music-status"><span class="equalizer"><i></i><i></i><i></i></span>${t("musicPlaying")}</div>` : state.musicAttempted ? `<div class="music-status muted">${t("musicBlocked")}</div>` : ""; return `<div class="intro-page"><div class="intro-toolbar"><button class="brand compact" data-route="home"><img src="images/paizo-logo.png" alt="">${t("brand")}</button><div class="intro-tools"><button class="music-control ${state.musicOn ? "active" : ""}" id="music-toggle" aria-pressed="${state.musicOn}">${ICONS.music} ${t("music")}</button><label class="volume"><span class="sr-only">${t("music")}</span><input id="music-volume" type="range" min="0.05" max="0.45" step="0.01" value="${audio.volume}"></label><button class="intro-exit" data-route="home">${ICONS.close} <span>${t("home")}</span></button></div></div><main class="intro-main"><div class="intro-progress-head"><span>${t("presentation")}</span><strong>${String(state.introStage + 1).padStart(2, "0")} / ${String(INTRO_STAGES.length).padStart(2, "0")}</strong></div><div class="intro-progress"><span style="width:${((state.introStage + 1) / INTRO_STAGES.length) * 100}%"></span></div><section class="intro-stage"><div class="intro-image"><img src="${stage[0]}" alt=""></div><div class="intro-copy"><div class="eyebrow">${t("stage")} ${state.introStage + 1} · 60″</div><h1>${state.lang === "el" ? stage[1] : stage[2]}</h1><p>${state.lang === "el" ? stage[3] : stage[4]}</p>${stage[5] === "topics" ? introTopicList() : ""}${stage[5] === "sources" ? introSourceList() : ""}${musicStatus}<div class="intro-actions"><button class="button quiet" id="intro-prev" ${state.introStage === 0 ? "disabled" : ""}>${ICONS.back} ${t("previousStage")}</button>${final ? `<button class="button coral" data-route="child-access">${t("continueGame")} ${ICONS.next}</button>` : `<button class="button coral" id="intro-next">${t("nextStage")} ${ICONS.next}</button>`}</div></div></section><div class="intro-dots" aria-hidden="true">${INTRO_STAGES.map((_, index) => `<i class="${index === state.introStage ? "active" : index < state.introStage ? "done" : ""}"></i>`).join("")}</div></main></div>`; }

function play() { const profile = activeProfile(); return pageFrame(`<main class="app-shell"><section class="app-heading"><div><div class="eyebrow">${t("child")}</div><h1>${state.lang === "el" ? "Γεια σου, " : "Hello, "}${esc(profile?.name || "Explorer")}!</h1><p>${state.lang === "el" ? "Διάλεξε ένα μάθημα και κάνε τη σημερινή σου ανακάλυψη." : "Choose a lesson and make today’s discovery."}</p></div><div class="mini-stats"><span><b>${profile?.stars || 0}</b>${ICONS.star} ${t("points")}</span><span><b>${profile?.rounds || 0}</b> ${t("quizzes")}</span></div></section><section><div class="section-title"><div><div class="eyebrow">${t("lessons")}</div><h2>${t("choose")}</h2></div><button class="text-button" data-route="parents">${t("parentArea")} ${ICONS.next}</button></div><div class="topic-grid">${TOPICS.map(topic => `<button class="topic-card" data-topic="${topic[0]}"><span>${topic[1]}</span><b>${state.lang === "el" ? topic[2] : topic[3]}</b><p>${esc(topicDescription(topic[0]))}</p><small>${t("ten")} ${ICONS.next}</small></button>`).join("")}</div></section></main>`); }

function firstAidBand() { const age = Number(activeProfile()?.age || 8); return age <= 8 ? "young" : age <= 11 ? "middle" : "teen"; }
function firstAidSafetyNotice() { const age = Number(activeProfile()?.age || 8); const level = age <= 8 ? (state.lang === "el" ? "Για την ηλικία σου μαθαίνουμε να μένεις ασφαλής και να βρίσκεις αμέσως έναν ενήλικα." : "At your age, we learn to stay safe and get an adult straight away.") : age <= 11 ? (state.lang === "el" ? "Για την ηλικία σου μαθαίνουμε να ζητάς βοήθεια, να λες πού είσαι και να μιλάς ήρεμα." : "At your age, we learn to get help, say where we are and speak calmly.") : (state.lang === "el" ? "Για την ηλικία σου μαθαίνουμε να δίνεις σαφείς πληροφορίες και να ακολουθείς την καθοδήγηση ενός ενήλικα ή του 112." : "At your age, we learn to give clear information and follow an adult’s or 112 operator’s guidance."); return `<aside class="first-aid-notice"><b>${state.lang === "el" ? "Βασική ασφάλεια" : "Safety first"}</b><span>${level} ${state.lang === "el" ? "Σε πραγματικό επείγον: κάλεσε ενήλικα και το 112." : "In a real emergency: get an adult and call 112."}</span>${emergency112Warning()}</aside>`; }
const QUESTION_CONTEXTS = {
  el: ["Στη γωνιά ανακάλυψης, η Μαρία συζητά με την ομάδα της. ", "Στην αυλή του σχολείου, ο Νικόλας παρατηρεί προσεκτικά πριν απαντήσει. ", "Στο σπίτι, η Ελένη ετοιμάζει μια μικρή δραστηριότητα μαζί με έναν ενήλικα. ", "Στην τάξη, η ομάδα διαβάζει το παράδειγμα και ελέγχει την ιδέα της. "],
  en: ["At the discovery corner, Maria discusses the idea with her group. ", "In the school yard, Nikos observes carefully before answering. ", "At home, Eleni prepares a small activity with an adult. ", "In class, the group reads the example and checks its idea. "]
};
const FIRST_AID_CONTEXTS = {
  el: ["Βρίσκεσαι στο σχολείο και βλέπεις ότι κάτι δεν πάει καλά. ", "Στην παιδική χαρά, παρατηρείς ένα περιστατικό χωρίς να πλησιάζεις τον κίνδυνο. ", "Στο σπίτι ενός φίλου, ένας ενήλικας είναι διαθέσιμος να βοηθήσει. "],
  en: ["You are at school and notice that something is wrong. ", "At the playground, you notice an incident without going near danger. ", "At a friend's home, a trusted adult is available to help. "]
};
function hashText(value) { let hash = 2166136261; for (let index = 0; index < value.length; index += 1) { hash ^= value.charCodeAt(index); hash = Math.imul(hash, 16777619); } return hash >>> 0; }
function seededShuffle(list, seed) { const copy = list.slice(); let value = hashText(String(seed)) || 1; for (let index = copy.length - 1; index > 0; index -= 1) { value = (Math.imul(value, 1664525) + 1013904223) >>> 0; const swap = value % (index + 1); [copy[index], copy[swap]] = [copy[swap], copy[index]]; } return copy; }
function mathQuestionPool(topic) { const pool = []; for (let index = 0; index < 40; index += 1) { const mode = index % 4; const first = 4 + ((index * 7) % 55); const second = 2 + ((index * 11) % (mode === 2 ? 8 : 35)); const firstTerm = mode === 1 ? Math.max(first, second + 5) : first; const rows = 2 + (index % 8) + (Math.floor(index / 4) % 5); const itemsPerRow = 2 + ((index * 3 + Math.floor(index / 4)) % 8); const answer = mode === 0 ? firstTerm + second : mode === 1 ? firstTerm - second : mode === 2 ? rows * itemsPerRow : Math.max(firstTerm, second); const question = mode === 0 ? (state.lang === "el" ? `Η ομάδα έχει ${firstTerm} κάρτες και βρίσκει άλλες ${second}. Πόσες κάρτες έχει τώρα;` : `The group has ${firstTerm} cards and finds ${second} more. How many cards does it have now?`) : mode === 1 ? (state.lang === "el" ? `Από ${firstTerm} αυτοκόλλητα χρησιμοποιούνται ${second}. Πόσα μένουν;` : `Out of ${firstTerm} stickers, ${second} are used. How many are left?`) : mode === 2 ? (state.lang === "el" ? `Υπάρχουν ${rows} σειρές με ${itemsPerRow} μολύβια η καθεμία. Πόσα μολύβια υπάρχουν;` : `There are ${rows} rows with ${itemsPerRow} pencils each. How many pencils are there?`) : (state.lang === "el" ? `Ποιος αριθμός είναι μεγαλύτερος: ${firstTerm} ή ${second};` : `Which number is greater: ${firstTerm} or ${second}?`); const correct = String(answer); const choices = mode === 3 ? [correct, String(Math.min(firstTerm, second)), String(firstTerm + second), String(Math.max(0, firstTerm - second))] : [correct, String(Math.max(0, answer - 1 - (index % 3))), String(answer + 1 + (index % 4)), String(answer + 4 + (index % 5))]; pool.push({ id: `math-generated-${state.lang}-${index}`, prompt: `${QUESTION_CONTEXTS[state.lang][index % QUESTION_CONTEXTS[state.lang].length]}${question}`, choices: seededShuffle([...new Set(choices)].concat([String(answer + 9)]).slice(0, 4), `math-choices-${index}`), correct, explanation: "", topic }); } return pool; }
function topicAssociationQuestion(topic, topicId, bits, rowIndex, context, variant) { const label = state.lang === "el" ? topic[2] : topic[3]; const otherLabels = seededShuffle(TOPICS.filter(item => item[0] !== topicId).map(item => state.lang === "el" ? item[2] : item[3]), `${topicId}-${rowIndex}-other-labels`).slice(0, 3); const forms = state.lang === "el" ? [`Η έννοια «${bits[1]}» εμφανίζεται σε μια δραστηριότητα. Σε ποια θεματική ταιριάζει;`, `Ποια θεματική βοηθά να εξερευνήσουμε την έννοια «${bits[1]}»;`, `Ένα παιδί συναντά το «${bits[1]}» σε άσκηση. Ποιο μάθημα έχει επιλέξει;`, `Πού ανήκει περισσότερο η ιδέα «${bits[1]}»;`, `Ποια από τις θεματικές συνδέεται με το «${bits[1]}»;`] : [`The idea “${bits[1]}” appears in an activity. Which theme does it fit?`, `Which theme helps us explore the idea “${bits[1]}”?`, `A child meets “${bits[1]}” in an activity. Which lesson was chosen?`, `Which lesson does the idea “${bits[1]}” belong to most?`, `Which theme connects with “${bits[1]}”?`]; return { id: `${topicId}-${state.lang}-association-${rowIndex}-${variant}`, prompt: `${context}${forms[rowIndex]}`, choices: seededShuffle([label, ...otherLabels], `${topicId}-${rowIndex}-association-${variant}`), correct: label, explanation: "", topic }; }
function createQuestionPool(topicId) { const topic = topicMap[topicId]; if (topicId === "math") return mathQuestionPool(topic); if (topicId === "firstAid") { const content = state.lang === "el" ? FIRST_AID_QUESTIONS : FIRST_AID_QUESTIONS_EN; const band = firstAidBand(); return content[band].flatMap((row, rowIndex) => FIRST_AID_CONTEXTS[state.lang].map((context, variant) => ({ id: `firstAid-${state.lang}-${band}-${rowIndex}-${variant}`, prompt: `${context}${row[0]}`, choices: seededShuffle(row.slice(1), `firstAid-${state.lang}-${band}-${rowIndex}-${variant}`), correct: row[1], explanation: "", topic }))); } return topic[4].flatMap((row, rowIndex) => { const bits = row.split("|"); const original = QUESTION_CONTEXTS[state.lang].map((context, variant) => ({ id: `${topicId}-${state.lang}-core-${rowIndex}-${variant}`, prompt: `${context}${state.lang === "el" ? bits[0] : translatePrompt(bits[0])}`, choices: seededShuffle(bits.slice(1), `${topicId}-${state.lang}-core-${rowIndex}-${variant}`), correct: bits[1], explanation: "", topic })); const associations = QUESTION_CONTEXTS[state.lang].map((context, variant) => topicAssociationQuestion(topic, topicId, bits, rowIndex, context, variant)); return [...original, ...associations]; }); }
function cycleKey(topicId) { return `${topicId}:${state.lang}:${topicId === "firstAid" ? firstAidBand() : "all"}`; }
function questionConceptId(question) { const parts = question.id.split("-"); if (parts[0] === "math") return question.id; if (parts[0] === "firstAid") return `${parts[0]}-${parts[1]}-${parts[2]}-${parts[3]}`; return `${parts[0]}-${parts[1]}-${parts[2]}-${parts[3]}`; }
function conceptBalancedDeck(pool, seed) { const groups = new Map(); pool.forEach(question => { const concept = questionConceptId(question); groups.set(concept, [...(groups.get(concept) || []), question.id]); }); const buckets = [...groups.values()].map(bucket => seededShuffle(bucket, `${seed}:${bucket[0]}`)); if (buckets.every(bucket => bucket.length === 1)) return seededShuffle(pool.map(question => question.id), seed); const layers = Math.max(...buckets.map(bucket => bucket.length)); const deck = []; for (let layer = 0; layer < layers; layer += 1) { const layerIds = buckets.map(bucket => bucket[layer]).filter(Boolean); deck.push(...seededShuffle(layerIds, `${seed}:layer:${layer}`)); } return deck; }
function takeNextQuestionDeck(topicId) { const profile = activeProfile(); profile.questionCycles = profile.questionCycles || {}; const key = cycleKey(topicId); const pool = createQuestionPool(topicId); const ids = pool.map(question => question.id); let cycle = profile.questionCycles[key]; const reset = !cycle || !Array.isArray(cycle.deck) || cycle.deck.length !== ids.length || cycle.deck.some(id => !ids.includes(id)) || cycle.cursor + 10 > ids.length; if (reset) { const nextCycle = Number(cycle?.cycle || 0) + 1; cycle = { cycle: nextCycle, cursor: 0, deck: conceptBalancedDeck(pool, `${profile.id}:${key}:${nextCycle}`) }; } const selectedIds = cycle.deck.slice(cycle.cursor, cycle.cursor + 10); cycle.cursor += selectedIds.length; profile.questionCycles[key] = cycle; saveFamily(); const byId = new Map(pool.map(question => [question.id, question])); return selectedIds.map(id => byId.get(id)).filter(Boolean).map(question => ({ ...question, answerIndex: question.choices.indexOf(question.correct) })); }
function buildQuestions(topicId) { return takeNextQuestionDeck(topicId); }
function translatePrompt(prompt) { const map = { "Πόσο κάνει": "What is", "Ποια λέξη": "Which word", "Ποιο": "Which", "Τι": "What", "Πώς": "How" }; const first = Object.keys(map).find(key => prompt.startsWith(key)); return first ? prompt.replace(first, map[first]) : prompt; }
function startRound(topicId, review = false) { speechSynthesis?.cancel(); state.topic = topicId; state.reviewing = review; state.questions = review ? state.missed.slice() : buildQuestions(topicId); state.index = 0; state.score = 0; if (!review) state.missed = []; state.selected = null; state.route = "quiz"; render(); if (state.autoRead) window.setTimeout(() => speak(state.questions[0].prompt), 120); }
function quiz() { const question = state.questions[state.index]; if (!question) return results(); const selected = state.selected; const answered = selected !== null; const correct = selected === question.answerIndex; const topic = question.topic; return `<div class="quiz-page"><header class="quiz-header"><button class="button quiet small" data-route="play">${ICONS.back} ${t("choose")}</button><div><span>${state.reviewing ? `${ICONS.refresh} ${t("review")}` : `${state.lang === "el" ? topic[2] : topic[3]}`}</span><strong>${t("question")} ${state.index + 1} ${t("outOf")} ${state.questions.length}</strong></div><div class="quiz-score">${ICONS.star} ${state.score}</div></header><main class="quiz-main">${topic[0] === "firstAid" ? firstAidSafetyNotice() : ""}<div class="quiz-progress"><span style="width:${(state.index / state.questions.length) * 100}%"></span></div><section class="question-card ${answered ? (correct ? "answered-correct" : "answered-wrong") : ""}">${state.reviewing ? `<div class="review-chip">${ICONS.refresh} ${t("review")}</div>` : ""}<div class="question-meta"><span class="topic-mark">${topic[1]}</span><div class="read-controls"><button id="read-question" class="circle-control" aria-label="${t("read")}">${ICONS.sound}</button><button id="auto-read" class="mini-toggle ${state.autoRead ? "active" : ""}" aria-pressed="${state.autoRead}">${t("autoRead")}: ${state.autoRead ? "ON" : "OFF"}</button><button id="sound-toggle" class="mini-toggle ${state.sound ? "active" : ""}" aria-pressed="${state.sound}">${t("sound")}: ${state.sound ? "ON" : "OFF"}</button></div></div><h1>${esc(question.prompt)}</h1><div class="answers">${question.choices.map((choice, index) => { const status = !answered ? "" : index === question.answerIndex ? "correct" : index === selected ? "wrong" : "muted"; return `<button class="answer ${status}" data-answer="${index}" ${answered ? "disabled" : ""}><span>${"ABCD"[index]}</span>${esc(choice)}${answered && index === question.answerIndex ? `<b>${ICONS.check}</b>` : ""}</button>`; }).join("")}</div>${answered ? `<div class="feedback ${correct ? "good" : "try"}">${correct ? `<div class="burst" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div>` : ""}<div class="feedback-icon">${correct ? ICONS.star : ICONS.refresh}</div><div><strong>${correct ? t("correct") : t("wrong")}</strong><p>${correct ? (state.lang === "el" ? "Συνέχισε έτσι — κάθε ερώτηση είναι ένα νέο βήμα." : "Keep going — every question is a new step.") : (state.lang === "el" ? "Θα τη συναντήσεις ξανά στην επανάληψη, χωρίς βιασύνη." : "You will see it again in the review, with no rush.")}</p></div><button class="button coral" id="quiz-next">${state.index === state.questions.length - 1 ? (state.reviewing ? t("finishReview") : t("roundComplete")) : t("continue")} ${ICONS.next}</button></div>` : ""}</section></main></div>`; }
function results() { const topic = topicMap[state.topic]; const total = state.questions.length || 10; const stars = state.score >= Math.ceil(total * .9) ? 3 : state.score >= Math.ceil(total * .6) ? 2 : 1; return pageFrame(`<main class="result-page"><section class="result-card"><div class="result-sparkles">✦ ✦ ✦</div><div class="result-trophy">${ICONS.star}</div><div class="eyebrow">${state.reviewing ? t("finishReview") : t("roundComplete")}</div><h1>${state.lang === "el" ? "Τα κατάφερες!" : "You did it!"}</h1><p>${t("youFound")} <strong>${state.score}</strong> ${t("outOf")} <strong>${total}</strong> ${state.lang === "el" ? "απαντήσεις στο μάθημα" : "answers in"} <strong>${state.lang === "el" ? topic[2] : topic[3]}</strong>.</p><div class="earned-stars">${[0,1,2].map(index => `<i class="${index < stars ? "on" : ""}">${ICONS.star}</i>`).join("")}</div>${!state.reviewing && state.missed.length ? `<div class="review-card"><div><b>${ICONS.refresh} ${t("reviewText")}</b><small>${state.missed.length} ${state.lang === "el" ? "ερωτήσεις περιμένουν" : "questions are waiting"}</small></div><button class="button quiet" id="review-mistakes">${t("review")} ${ICONS.refresh}</button></div>` : state.reviewing ? `<div class="review-card compact"><b>${ICONS.check} ${t("noMistakes")}</b></div>` : ""}<div class="result-actions"><button class="button coral" id="again-round">${t("again")} ${ICONS.refresh}</button><button class="button quiet" data-route="play">${t("another")} ${ICONS.next}</button></div></section></main>`); }

function childAccess() { if (!family.parent.hash) { state.pinSetupDestination = "children"; return parentPinSetup(true); } if (!state.childAccessUnlocked) return childPinGate(); return childPicker(); }
function childPinGate() { const isGreek = state.lang === "el"; return pageFrame(`<main class="gate-page"><section class="gate-card"><div class="gate-icon">${ICONS.lock}</div><div class="eyebrow">${isGreek ? "Ασφαλής είσοδος" : "Secure entry"}</div><h1>${isGreek ? "Άνοιξε την εφαρμογή" : "Open the app"}</h1><p>${isGreek ? "Ο γονέας εισάγει τον PIN και μετά το παιδί διαλέγει το δικό του προφίλ με ένα πάτημα." : "A parent enters the PIN, then the child chooses their own profile with one tap."}</p><label>${t("parentPin")}<input id="unlock-pin" type="password" inputmode="numeric" autocomplete="current-password" maxlength="24"></label><p class="form-message" id="parent-message"></p><div class="form-actions"><button class="button coral" id="unlock-child-access">${isGreek ? "Συνέχεια στα προφίλ" : "Continue to profiles"} ${ICONS.next}</button><button class="button quiet" data-route="home">${t("back")}</button></div></section></main>`); }
function childPicker() { const isGreek = state.lang === "el"; return pageFrame(`<main class="gate-page"><section class="gate-card child-picker"><div class="gate-icon">${ICONS.play}</div><div class="eyebrow">${t("child")}</div><h1>${isGreek ? "Διάλεξε το προφίλ σου" : "Choose your profile"}</h1><p>${isGreek ? "Πάτησε μία φορά στο όνομά σου για να ανοίξει αμέσως το δικό σου παιχνίδι και η πρόοδός σου." : "Tap your name once to open your game and progress straight away."}</p><div class="child-profile-picker">${family.profiles.map(profile => `<button class="child-profile-choice ${profile.id === family.activeId ? "selected" : ""}" data-select-profile="${profile.id}"><span class="avatar">${esc(profile.name.slice(0,1).toUpperCase())}</span><span><b>${esc(profile.name)}</b><small>${profile.age} ${isGreek ? "ετών" : "years"} · ${profile.correct || 0} ${t("learning")}</small></span><i>${ICONS.play}</i></button>`).join("")}</div><div class="form-actions"><button class="button quiet" data-route="home">${ICONS.back} ${t("home")}</button><button class="text-button" data-route="parents">${t("parentArea")} ${ICONS.next}</button></div></section></main>`); }
function parentGate() { const isConfigured = Boolean(family.parent.hash); if (!isConfigured) { state.pinSetupDestination = "parent"; return parentPinSetup(); } if (!state.parentOpen) return pageFrame(`<main class="gate-page"><section class="gate-card"><div class="gate-icon">${ICONS.lock}</div><div class="eyebrow">${t("parentArea")}</div><h1>${t("unlock")}</h1><p>${t("parentInfo")}</p><label>${t("parentPin")}<input id="unlock-pin" type="password" inputmode="numeric" autocomplete="current-password" maxlength="24"></label><p class="form-message" id="parent-message"></p><div class="form-actions"><button class="button coral" id="unlock-parent">${t("unlock")} ${ICONS.next}</button><button class="button quiet" data-route="play">${t("back")}</button></div></section></main>`); return parentDashboard(); }
function parentPinSetup(forChildren = false) { const isGreek = state.lang === "el"; const title = forChildren ? (isGreek ? "Δημιούργησε γονικό PIN" : "Create a parent PIN") : t("createPin"); const text = forChildren ? (isGreek ? "Δημιούργηστε έναν PIN με τουλάχιστον 6 χαρακτήρες. Στη συνέχεια το παιδί θα μπορεί να διαλέγει το προφίλ του με ένα πάτημα." : "Create a PIN with at least 6 characters. Then the child can choose their profile with one tap.") : t("parentInfo"); return pageFrame(`<main class="gate-page"><section class="gate-card"><div class="gate-icon">${ICONS.lock}</div><div class="eyebrow">${t("parentArea")}</div><h1>${title}</h1><p>${text}</p><label>${t("parentPin")}<input id="new-pin" type="password" inputmode="numeric" autocomplete="new-password" minlength="6" maxlength="24"></label><label>${t("confirmPin")}<input id="confirm-pin" type="password" inputmode="numeric" autocomplete="new-password" minlength="6" maxlength="24"></label><p class="form-message" id="parent-message"></p><div class="form-actions"><button class="button coral" id="save-parent-pin">${t("save")} ${ICONS.next}</button><button class="button quiet" data-route="home">${t("back")}</button></div></section></main>`); }
function parentDashboard() { return pageFrame(`<main class="parent-page"><section class="parent-heading"><div><div class="eyebrow">${t("parentArea")}</div><h1>${state.lang === "el" ? "Οικογενειακή εικόνα" : "Family overview"}</h1><p>${t("parentInfo")}</p></div><button class="button quiet" id="lock-parent">${ICONS.lock} ${t("back")}</button></section><div class="parent-grid"><section class="parent-panel"><div class="panel-head"><h2>${t("child")}</h2><span>${family.profiles.length}/12</span></div><div class="profiles">${family.profiles.map(profile => `<article class="profile ${profile.id === family.activeId ? "selected" : ""}" data-profile-id="${profile.id}"><div class="avatar">${esc(profile.name.slice(0,1).toUpperCase())}</div><div><b>${esc(profile.name)}</b><small>${profile.age} ${state.lang === "el" ? "ετών" : "years"} · ${profile.correct || 0} ${t("learning")}</small></div><button class="text-button profile-open" data-select-profile="${profile.id}">${profile.id === family.activeId ? `${ICONS.play} ${state.lang === "el" ? "Συνέχισε" : "Continue"}` : `${t("select")} ${ICONS.next}`}</button>${family.profiles.length > 1 ? `<button class="delete-profile" data-delete-profile="${profile.id}" aria-label="${ICONS.close}">${ICONS.close}</button>` : ""}</article>`).join("")}</div><form id="add-profile-form" class="new-profile"><h3>${t("addProfile")}</h3><div><label>${t("name")}<input id="profile-name" maxlength="24" required></label><label>${t("age")}<select id="profile-age">${Array.from({length:10}, (_, index) => `<option value="${index + 6}">${index + 6}</option>`).join("")}</select></label></div><button class="button coral" type="submit">${ICONS.next} ${t("addProfile")}</button></form></section><section class="parent-panel"><div class="panel-head"><h2>${t("summary")}</h2><span>${t("local")}</span></div><div class="progress-table">${family.profiles.map(profile => `<div><b>${esc(profile.name)}</b><span>${ICONS.star} ${profile.stars || 0} · ${profile.rounds || 0} ${t("quizzes")}</span><i><em style="width:${Math.min(100, ((profile.correct || 0) / Math.max(1, (profile.rounds || 1) * 10)) * 100)}%"></em></i></div>`).join("")}</div><div class="backup-box"><h3>${t("backup")}</h3><p>${state.lang === "el" ? "Δημιουργήστε κρυπτογραφημένο αρχείο για μεταφορά προφίλ και προόδου σε άλλη συσκευή." : "Create an encrypted file to move profiles and progress to another device."}</p><label>${t("backupPin")}<input id="backup-pin" type="password" minlength="6" autocomplete="new-password"></label><div class="form-actions"><button class="button quiet" id="download-backup">${ICONS.download} ${t("backup")}</button></div></div><div class="backup-box restore-box"><h3>${t("restore")}</h3><p>${t("chooseBackup")}</p><input id="restore-file" type="file" accept="application/json"><label>${t("backupPin")}<input id="restore-pin" type="password" minlength="6" autocomplete="current-password"></label><button class="button quiet" id="restore-backup">${ICONS.upload} ${t("restore")}</button></div></section></div></main>`); }

function render() { document.documentElement.lang = state.lang; localStorage.setItem(LANG_STORE, state.lang); window.clearInterval(state.introTimer); if (state.route !== "intro") { audio.pause(); } if (state.route === "home") app.innerHTML = home(); else if (state.route === "intro") { app.innerHTML = intro(); scheduleIntro(); } else if (state.route === "child-access") app.innerHTML = childAccess(); else if (state.route === "play") app.innerHTML = play(); else if (state.route === "quiz") app.innerHTML = quiz(); else if (state.route === "results") app.innerHTML = results(); else if (state.route === "parents") app.innerHTML = parentGate(); else if (state.route === "terms") app.innerHTML = terms(); if (state.route === "parents" && state.parentOpen) document.querySelector(".parent-page")?.insertAdjacentHTML("beforeend", `${shortcutGuide()}${firstAidSourcesPanel()}`); bindPrimaryActivation(); bind(); if (state.supportOpen) window.requestAnimationFrame(() => document.getElementById("close-support-dialog")?.focus()); }
function scheduleIntro() { state.introTimer = window.setInterval(() => { if (state.introStage < INTRO_STAGES.length - 1) { state.introStage += 1; render(); } }, 6000); }
function moveIntro(delta) { state.introStage = Math.min(INTRO_STAGES.length - 1, Math.max(0, state.introStage + delta)); render(); }

let primaryActivationBound = false;
function bindPrimaryActivation() {
  if (primaryActivationBound) return;
  primaryActivationBound = true;
  app.addEventListener("click", event => {
    if (!(event.target instanceof Element)) return;
    const routeButton = event.target.closest("[data-route]");
    const topicButton = event.target.closest("[data-topic]");
    const profileButton = event.target.closest("[data-select-profile]");
    const supportButton = event.target.closest("[data-support]");
    if (routeButton) {
      event.preventDefault();
      event.stopImmediatePropagation();
      state.route = routeButton.dataset.route;
      if (state.route === "child-access") { state.pinSetupDestination = "children"; state.childAccessUnlocked = false; }
      if (state.route === "parents") { state.pinSetupDestination = "parent"; }
      if (state.route === "intro") { state.introStage = 0; startMusic(); }
      render();
      return;
    }
    if (topicButton) {
      event.preventDefault();
      event.stopImmediatePropagation();
      if (state.route === "home") { state.pinSetupDestination = "children"; state.childAccessUnlocked = false; state.route = "child-access"; render(); return; }
      startRound(topicButton.dataset.topic);
      return;
    }
    if (profileButton) {
      event.preventDefault();
      event.stopImmediatePropagation();
      activateProfile(profileButton.dataset.selectProfile);
      return;
    }
    if (supportButton) {
      event.preventDefault();
      event.stopImmediatePropagation();
      state.supportOpen = true;
      render();
    }
  }, true);
}

function bind() {
  document.getElementById("close-support")?.addEventListener("click", () => { state.supportOpen = false; render(); });
  document.getElementById("close-support-dialog")?.addEventListener("click", () => { state.supportOpen = false; render(); });
  document.querySelectorAll("[data-language]").forEach(button => button.addEventListener("click", () => { state.lang = button.dataset.language; render(); }));
  document.querySelectorAll("[data-answer]").forEach(button => button.addEventListener("click", () => { if (state.selected !== null) return; state.selected = Number(button.dataset.answer); const correct = state.selected === state.questions[state.index].answerIndex; if (correct) { state.score += 1; } else if (!state.reviewing) { state.missed.push(state.questions[state.index]); } playTone(correct); render(); }));
  document.getElementById("quiz-next")?.addEventListener("click", () => { if (state.index === state.questions.length - 1) { updateProfileRound(); state.route = "results"; render(); return; } state.index += 1; state.selected = null; render(); if (state.autoRead) window.setTimeout(() => speak(state.questions[state.index].prompt), 120); });
  document.getElementById("read-question")?.addEventListener("click", () => speak(state.questions[state.index].prompt));
  document.getElementById("auto-read")?.addEventListener("click", () => { state.autoRead = !state.autoRead; render(); if (state.autoRead) speak(state.questions[state.index].prompt); });
  document.getElementById("sound-toggle")?.addEventListener("click", () => { state.sound = !state.sound; render(); });
  document.getElementById("again-round")?.addEventListener("click", () => startRound(state.topic));
  document.getElementById("review-mistakes")?.addEventListener("click", () => { state.reviewing = true; state.questions = state.missed.slice(); state.index = 0; state.score = 0; state.selected = null; state.route = "quiz"; render(); });
  document.getElementById("intro-next")?.addEventListener("click", () => moveIntro(1));
  document.getElementById("intro-prev")?.addEventListener("click", () => moveIntro(-1));
  document.getElementById("music-toggle")?.addEventListener("click", () => { if (state.musicOn) stopMusic(); else startMusic(); render(); });
  document.getElementById("music-volume")?.addEventListener("input", event => { audio.volume = Number(event.target.value); });
  document.getElementById("save-parent-pin")?.addEventListener("click", async () => { const a = document.getElementById("new-pin").value; const b = document.getElementById("confirm-pin").value; if (a.length < 6 || a !== b) { document.getElementById("parent-message").textContent = t("pinMismatch"); return; } const salt = randomId(); family.parent = { salt, hash: await digest(`${salt}:${a}`) }; saveFamily(); if (state.pinSetupDestination === "children") { state.childAccessUnlocked = true; state.parentOpen = false; state.route = "child-access"; } else { state.parentOpen = true; state.route = "parents"; } render(); });
  document.getElementById("unlock-parent")?.addEventListener("click", async () => { const value = document.getElementById("unlock-pin").value; if (await digest(`${family.parent.salt}:${value}`) !== family.parent.hash) { document.getElementById("parent-message").textContent = t("unlockFail"); return; } state.parentOpen = true; render(); });
  document.getElementById("unlock-child-access")?.addEventListener("click", async () => { const value = document.getElementById("unlock-pin").value; if (await digest(`${family.parent.salt}:${value}`) !== family.parent.hash) { document.getElementById("parent-message").textContent = t("unlockFail"); return; } state.childAccessUnlocked = true; state.parentOpen = false; state.route = "child-access"; render(); });
  document.getElementById("lock-parent")?.addEventListener("click", () => { state.parentOpen = false; state.route = "play"; render(); });
  document.querySelectorAll("[data-delete-profile]").forEach(button => button.addEventListener("click", () => { const id = button.dataset.deleteProfile; family.profiles = family.profiles.filter(profile => profile.id !== id); if (family.activeId === id) family.activeId = family.profiles[0].id; saveFamily(); render(); }));
  document.getElementById("add-profile-form")?.addEventListener("submit", event => { event.preventDefault(); if (family.profiles.length >= 12) return setToast(t("profileLimit")); const name = document.getElementById("profile-name").value.trim().replace(/[<>]/g, ""); const age = Number(document.getElementById("profile-age").value); if (name.length < 2) return; family.profiles.push({ id: randomId(), name, age, stars: 0, correct: 0, rounds: 0, mistakes: 0 }); saveFamily(); render(); });
  document.getElementById("download-backup")?.addEventListener("click", async () => { const password = document.getElementById("backup-pin").value; if (password.length < 6) return setToast(t("pinMismatch")); try { const blob = new Blob([await encryptedBackup(password)], { type: "application/json" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `paizomath-backup-${new Date().toISOString().slice(0,10)}.json`; link.click(); URL.revokeObjectURL(url); setToast(state.lang === "el" ? "Το κρυπτογραφημένο backup δημιουργήθηκε." : "Encrypted backup created."); } catch { setToast(state.lang === "el" ? "Δεν δημιουργήθηκε το backup." : "Backup could not be created."); } });
  document.getElementById("restore-backup")?.addEventListener("click", async () => { const file = document.getElementById("restore-file").files[0]; const password = document.getElementById("restore-pin").value; if (!file || password.length < 6) return setToast(state.lang === "el" ? "Επιλέξτε αρχείο και κωδικό backup." : "Choose a backup file and password."); if (!confirm(t("restoreWarning"))) return; try { family = await restoreEncryptedBackup(await file.text(), password); saveFamily(); setToast(state.lang === "el" ? "Η επαναφορά ολοκληρώθηκε." : "Restore complete."); render(); } catch { setToast(state.lang === "el" ? "Το backup ή ο κωδικός δεν είναι σωστά." : "The backup or password is not correct."); } });
}
function updateProfileRound() { if (state.reviewing) return; const profile = activeProfile(); if (!profile) return; profile.correct = (profile.correct || 0) + state.score; profile.stars = (profile.stars || 0) + state.score; profile.rounds = (profile.rounds || 0) + 1; profile.mistakes = (profile.mistakes || 0) + state.missed.length; saveFamily(); }
function startMusic() { state.musicAttempted = true; state.musicOn = true; localStorage.setItem(MUSIC_STORE, "on"); audio.play().then(() => { state.musicOn = true; }).catch(() => { state.musicOn = false; render(); }); }
function stopMusic() { state.musicOn = false; state.musicAttempted = true; localStorage.setItem(MUSIC_STORE, "off"); audio.pause(); }
render();
